-- 多租户、多用户、多代理用户、多库 SQL audit 测试 workload
-- 执行前提：使用 sys 租户 root 用户执行，具备创建租户/用户/库权限。
-- 验证结果。均可正常记录。
CREATE RESOURCE UNIT IF NOT EXISTS ebpf_audit_unit MAX_CPU 1, MEMORY_SIZE '3G', MAX_IOPS 1024, MIN_IOPS 1024, LOG_DISK_SIZE '3G';
CREATE RESOURCE POOL IF NOT EXISTS ebpf_audit_pool_a UNIT = 'ebpf_audit_unit', UNIT_NUM = 1;
CREATE RESOURCE POOL IF NOT EXISTS ebpf_audit_pool_b UNIT = 'ebpf_audit_unit', UNIT_NUM = 1;
CREATE TENANT IF NOT EXISTS ebpf_audit_tenant_a RESOURCE_POOL_LIST = ('ebpf_audit_pool_a') SET ob_tcp_invited_nodes = '%';
CREATE TENANT IF NOT EXISTS ebpf_audit_tenant_b RESOURCE_POOL_LIST = ('ebpf_audit_pool_b') SET ob_tcp_invited_nodes = '%';

-- tenant_a: root 执行
CREATE DATABASE IF NOT EXISTS ebpf_audit_db_a1;
CREATE DATABASE IF NOT EXISTS ebpf_audit_db_a2;
DROP TABLE IF EXISTS ebpf_audit_db_a1.identity_audit_case;
DROP TABLE IF EXISTS ebpf_audit_db_a2.identity_audit_case;
CREATE TABLE ebpf_audit_db_a1.identity_audit_case (
  id INT NOT NULL,
  k INT NOT NULL,
  c VARCHAR(120) NOT NULL,
  PRIMARY KEY (id)
);
CREATE TABLE ebpf_audit_db_a2.identity_audit_case (
  id INT NOT NULL,
  k INT NOT NULL,
  c VARCHAR(120) NOT NULL,
  PRIMARY KEY (id)
);
CREATE USER IF NOT EXISTS audit_user_a IDENTIFIED BY '';
CREATE USER IF NOT EXISTS proxy_user_a IDENTIFIED BY '';
GRANT ALL PRIVILEGES ON ebpf_audit_db_a1.* TO audit_user_a;
GRANT ALL PRIVILEGES ON ebpf_audit_db_a2.* TO audit_user_a;
GRANT ALL PRIVILEGES ON *.* TO proxy_user_a; 
